{
  "root_causes": [
    {
      "service": "ts-security-service",
      "fault_kind": "network_loss",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, attr_span_kind, span_name, count(*) n, quantile_cont(duration,0.5)/1e6 p50_ms, max(duration)/1e6 max_ms FROM abnormal_traces WHERE service_name='ts-security-service' AND attr_span_kind='Client' GROUP BY ALL",
          "claim": "Security's outbound GET client spans to order-service reach ~8 s median and up to ~130 s, versus ~7 ms in normal."
        },
        {
          "kind": "trace",
          "sql": "SELECT service_name, attr_span_kind, span_name, duration/1e6 ms, time FROM abnormal_traces WHERE service_name IN ('ts-security-service','ts-order-service') AND span_name LIKE '%securityConfigs%' OR span_name LIKE '%order/security%' ORDER BY time LIMIT 20",
          "claim": "In one trace, security's client GET lasts ~57 s while order-service's server span takes only ~8 ms, starting ~3 s late."
        },
        {
          "kind": "metric",
          "sql": "SELECT metric, attr_source, attr_destination, sum(value) total FROM abnormal_metrics_sum WHERE metric='hubble_drop_total' AND ((attr_source LIKE '%ts-order-service%' AND attr_destination LIKE '%ts-security-service%') OR (attr_source LIKE '%ts-security-service%' AND attr_destination LIKE '%ts-order-service%')) GROUP BY ALL",
          "claim": "Hubble records 77 dropped packets from order-service to security-service pods; normal period shows none on this pair."
        },
        {
          "kind": "metric",
          "sql": "SELECT metric, attr_source, attr_destination, sum(value) total FROM abnormal_metrics_sum WHERE metric='hubble_tcp_flags_total' AND attr_source LIKE '%ts-order-service%' AND attr_destination LIKE '%ts-security-service%' GROUP BY ALL",
          "claim": "TCP flag counts on the order-to-security connection rise to about 817 in the incident, versus about 113 in normal, consistent with retransmissions."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-security-service",
      "to": "ts-preserve-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, attr_span_kind, count(*) n, quantile_cont(duration,0.95)/1e6 p95_ms, sum(CASE WHEN attr_status_code='Error' THEN 1 ELSE 0 END) errs FROM abnormal_traces WHERE (service_name='ts-preserve-service' AND attr_span_kind='Server') OR (service_name='ts-security-service' AND attr_span_kind='Client') GROUP BY ALL",
          "claim": "Preserve server p95 rises from ~1.6 s to ~114 s, and security's client calls rise from ~7.5 ms to ~124 s p95."
        }
      ]
    },
    {
      "from": "ts-preserve-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, attr_span_kind, span_name, count(*) n, quantile_cont(duration,0.95)/1e6 p95_ms FROM abnormal_traces WHERE service_name='ts-ui-dashboard' AND span_name LIKE '%preserve%' GROUP BY ALL",
          "claim": "User-facing preserve requests at ui-dashboard reach ~20 s p95 in the incident, versus ~1.6 s in normal, with failed requests."
        }
      ]
    }
  ]
}
